function html(response, status, content) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(content);
}

async function parseForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    chunks.push(chunk);
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    let appliedRange = dueRange(url.searchParams);
    async function readForm(request) {
      const form = await parseForm(request);
      appliedRange = dueRange(form);
      return form;
    }
    // All project responses and edit redirects preserve this request's applied range.
    const projectPage = (project, filter, error, priority, range = appliedRange) =>
      renderProjectPage(project, filter, error, priority, range);
    const projectLocation = (id, filter, priority, range = appliedRange) =>
      buildProjectLocation(id, filter, priority, range);
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      html(response, 200, projectsPage('', projectFilter(url.searchParams.get('filter'))));
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        html(response, 400, projectsPage('Project name is required'));
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/due-range$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      const from = (form.get('rangeFrom') || '').trim();
      const through = (form.get('rangeThrough') || '').trim();
      const error = (from && !validDueDate(from)) || (through && !validDueDate(through))
        ? 'Due range must use valid YYYY-MM-DD dates'
        : from && through && from > through ? 'Due from must not be after Due through' : '';
      if (error) {
        html(response, 400, projectPage(project, filter, error, priority, dueRange(form)));
        return;
      }
      response.writeHead(303, { Location: projectLocation(id, filter, priority, { from, through }) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/default-priority$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const selectedPriority = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived project is read-only', selectedPriority));
        return;
      }
      const priority = form.get('priority');
      if (!priorities.includes(priority)) {
        html(response, 400, projectPage(project, filter, 'Invalid task priority', selectedPriority));
        return;
      }
      setDefaultPriority.run(priority, id);
      response.writeHead(303, { Location: projectLocation(id, filter, selectedPriority) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/rename$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived project is read-only', priority));
        return;
      }
      const name = (form.get('name') || '').trim();
      if (!name) {
        html(response, 400, projectPage(project, filter, 'Project name is required', priority));
        return;
      }
      renameProject.run(name, id);
      response.writeHead(303, { Location: projectLocation(id, filter, priority) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/(archive|restore)$/.test(url.pathname)) {
      const [, , projectId, action] = url.pathname.split('/');
      const id = Number(projectId);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      setArchived.run(action === 'archive' ? 1 : 0, id);
      response.writeHead(303, { Location: action === 'archive' ? '/' : '/?filter=Archived' });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const id = Number(url.pathname.split('/')[2]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      html(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', priorityFilter(url.searchParams.get('priorityFilter'))));
    } else if (request.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+(?:\/(?:rename|priority|due-date|move))?)?$/.test(url.pathname)) {
      const [, , projectId, , taskId, action] = url.pathname.split('/');
      const id = Number(projectId);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : null;
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const selectedPriority = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived project is read-only', selectedPriority));
        return;
      }
      if (action === 'move') {
        if (!findTask.get(Number(taskId), id)) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        const destinationId = Number(form.get('destination'));
        const destination = Number.isSafeInteger(destinationId) ? findProject.get(destinationId) : null;
        if (!destination || destination.archived || destinationId === id) {
          html(response, 400, projectPage(project, filter, 'Choose an active destination project', selectedPriority));
          return;
        }
        transaction(() => {
          rememberDestination.run(Number(taskId), destinationId, destinationId);
          moveTask.run(destinationId, Number(taskId), destinationId, Number(taskId), id);
        });
      } else if (action === 'due-date') {
        if (!findTask.get(Number(taskId), id)) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        const dueDate = (form.get('dueDate') || '').trim();
        if (dueDate && !validDueDate(dueDate)) {
          html(response, 400, projectPage(project, filter, 'Due date must be a valid YYYY-MM-DD date', selectedPriority));
          return;
        }
        setTaskDueDate.run(dueDate, Number(taskId), id);
      } else if (action === 'priority') {
        if (!findTask.get(Number(taskId), id)) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        const priority = form.get('priority');
        if (!priorities.includes(priority)) {
          html(response, 400, projectPage(project, filter, 'Invalid task priority', selectedPriority));
          return;
        }
        setTaskPriority.run(priority, Number(taskId), id);
      } else if (action === 'rename') {
        if (!findTask.get(Number(taskId), id)) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(response, 400, projectPage(project, filter, 'Task title is required', selectedPriority));
          return;
        }
        renameTask.run(title, Number(taskId), id);
      } else if (taskId) {
        const result = updateTask.run(form.get('completed') === '1' ? 1 : 0, Number(taskId), id);
        if (!result.changes) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
      } else {
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(response, 400, projectPage(project, filter, 'Task title is required', selectedPriority));
          return;
        }
        transaction(() => {
          const result = createTask.run(id, title, project.default_priority, id);
          rememberCreatedTask.run(result.lastInsertRowid);
        });
      }
      response.writeHead(303, { Location: projectLocation(id, filter, selectedPriority) });
      response.end();
    } else {
      html(response, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    console.error(error);
    html(response, error.status || 500, page('Error', '<h1>Unable to complete request</h1>'));
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

test('inclusive due ranges intersect filters and survive edits without changing task data', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-range-'));
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'db.sqlite') },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  try {
    const base = await new Promise((resolve, reject) => {
      child.once('error', reject);
      child.once('exit', () => reject(new Error('Server exited')));
      child.stdout.on('data', (data) => {
        const port = String(data).match(/port (\d+)/);
        if (port) resolve(`http://127.0.0.1:${port[1]}`);
      });
    });
    const post = (path, data = {}) => fetch(base + path, {
      method: 'POST', body: new URLSearchParams(data), redirect: 'manual',
    });
    const get = async (path) => (await fetch(base + path)).text();
    const rows = (html) => [...html.matchAll(/aria-label="Complete ([^"]+)"/g)].map((m) => m[1]);
    await post('/projects', { name: 'Dates' });
    for (const title of ['Before', 'First', 'Last', 'After', 'Undated']) {
      await post('/projects/1/tasks', { title });
    }
    for (const [id, dueDate] of [[1, '2024-02-28'], [2, '2024-02-29'], [3, '2024-03-01'], [4, '2024-03-02']]) {
      await post(`/projects/1/tasks/${id}/due-date`, { dueDate });
    }
    const state = { filter: 'All', priorityFilter: 'All', dueFrom: '2024-02-29', dueThrough: '2024-03-01' };
    const apply = (rangeFrom, rangeThrough, previous = state) => post('/projects/1/due-range', { ...previous, rangeFrom, rangeThrough });
    let response = await apply(' 2024-02-29 ', ' 2024-03-01 ');
    const location = response.headers.get('location');
    assert.equal(response.status, 303);
    assert.deepEqual(rows(await get(location)), ['First', 'Last']);
    assert.deepEqual(rows(await get('/projects/1?dueFrom=2024-03-01')), ['Last', 'After']);
    assert.deepEqual(rows(await get('/projects/1?dueThrough=2024-02-29')), ['Before', 'First']);
    for (const invalid of ['0000-01-01', '1900-02-29', '2024-04-31', '2024-2-29', '10000-01-01', 'bad']) {
      response = await apply(invalid, '');
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.match(html, /Due range must use valid YYYY-MM-DD dates/);
      assert.deepEqual(rows(html), ['First', 'Last']);
    }
    response = await apply('2024-03-02', '2024-02-29');
    assert.match(await response.text(), /Due from must not be after Due through/);
    await post('/projects/1/tasks/2', { ...state, completed: '1' });
    await post('/projects/1/tasks/2/priority', { ...state, priority: 'High' });
    const selected = { ...state, filter: 'Completed', priorityFilter: 'High' };
    const selectedLocation = '/projects/1?' + new URLSearchParams(selected);
    assert.deepEqual(rows(await get(selectedLocation)), ['First']);
    response = await post('/projects/1/tasks/2/rename', { ...selected, title: 'Renamed' });
    assert.equal(response.headers.get('location'), selectedLocation);
    assert.deepEqual(rows(await get(selectedLocation)), ['Renamed']);
    response = await post('/projects/1/tasks/2/due-date', { ...selected, dueDate: '2024-03-02' });
    assert.deepEqual(rows(await get(response.headers.get('location'))), []);
    await post('/projects/1/tasks/2/due-date', { ...selected, dueDate: '2024-02-29' });
    for (const [endpoint, data] of [['rename', { name: 'New name' }], ['default-priority', { priority: 'High' }], ['tasks', { title: 'New task' }]]) {
      response = await post(`/projects/1/${endpoint}`, { ...selected, ...data });
      assert.equal(response.headers.get('location'), selectedLocation);
      assert.deepEqual(rows(await get(selectedLocation)), ['Renamed']);
    }
    assert.match(await get('/'), /project-summary">1\/6 completed/);
    await post('/projects/1/archive');
    response = await apply('2024-02-29', '2024-02-29', selected);
    assert.equal(response.status, 303);
    const archived = await get(response.headers.get('location'));
    assert.deepEqual(rows(archived), ['Renamed']);
    assert.match(archived, /id="due-from"[^>]*value="2024-02-29">/);
    assert.match(archived, /aria-label="Complete Renamed" checked disabled/);
    await post('/projects/1/restore');
    assert.deepEqual(rows(await get(selectedLocation)), ['Renamed']);
    response = await apply(' ', ' ', selected);
    assert.deepEqual(rows(await get(response.headers.get('location'))), ['Renamed']);
    const reopened = await get('/projects/1');
    assert.match(reopened, /id="due-from"[^>]*value="">/);
    assert.match(reopened, /id="due-through"[^>]*value="">/);
    assert.equal(rows(reopened).length, 6);
  } finally {
    const exited = new Promise((resolve) => child.once('exit', resolve));
    child.kill('SIGTERM');
    await exited;
    await rm(directory, { recursive: true, force: true });
  }
});

